"use client";

import { useCallback, useEffect, useId, useRef, useState, type ChangeEvent, type ComponentProps, type FocusEvent, type KeyboardEvent, type MouseEvent } from "react";

import { IconAlertCircle } from "@rhs-ui/icons";
import { InputGroup, InputGroupInput } from "@rhs-ui/primitives/input-group";
import { trackPress, whenReleased } from "@rhs-ui/primitives/shorthand-number-field/blur-guard";
import { DEFAULT_LABELS, formatFull, readShorthand, write, type ShorthandDisplay, type ShorthandLabels } from "@rhs-ui/primitives/shorthand-number-field/shorthand";
import { cn } from "@/lib/utils";

export type { ShorthandDisplay, ShorthandLabels } from "@rhs-ui/primitives/shorthand-number-field/shorthand";

export interface ShorthandNumberFieldProps extends Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "min" | "max" | "name" | "role" | "inputMode" | "children"> {
  /** The number, when you control it. Null while the field is empty. */
  value?: number | null;
  /** The number to start with, when you do not control it. */
  defaultValue?: number | null;
  /**
   * Called with a plain number when the field is committed (Enter, or leaving it), and with null when it was emptied or could not be read.
   * `valid` is true when there is a number inside `min` and `max`; one outside them is still reported, so a form can say why.
   */
  onValueChange?: (value: number | null, state: { valid: boolean }) => void;
  /** The locale that writes the figures and decides the decimal sign. Default "en-US". */
  locale?: string;
  /** The lowest number allowed. */
  min?: number;
  /** The highest number allowed. */
  max?: number;
  /** A word after the number: "followers", "EUR". It sits in the field, is ignored if typed again, and is said with the figure. */
  unit?: string;
  /** How the number is written when the field is left: "full" with grouping (1,200) or "compact" short with a letter (1.2K). Default "full". */
  display?: ShorthandDisplay;
  /** The field's name for a plain form submit: the number with a point as the decimal sign, or empty. */
  name?: string;
  /** The words the field says, for another language or your own voice. */
  labels?: Partial<ShorthandLabels>;
}

const EXAMPLES = "250k, 1.2M, 3b or 2 million";
// The group's own focus border would win over the red one while the cursor is still in a field that is wrong, so the red is asked for in the focused state too.
const WRONG = "border-destructive has-[input:focus-visible]:border-destructive has-[input:focus-visible]:ring-destructive/30";

/**
 * A number field that reads shorthand. Type 250k, 1.2M, 3b or "2 million" and
 * the full figure is written under the field as you go, so the zeros are never
 * counted by eye. The decimal sign is the locale's and the other one is
 * understood too (1,2k and 1.2k both mean 1200, while 1,200 is twelve hundred),
 * a currency sign in front or the field's unit behind is ignored, and the
 * sums run on the digits, so 1.1k is exactly 1100. The number is committed with
 * Enter or when the field is left, where the text is rewritten the way
 * `display` says; Escape puts back the last number. What cannot be read, or is
 * outside `min` and `max`, is explained in words and not only refused. It suits
 * targets, budgets and audience sizes, where typing a row of zeros is how
 * mistakes happen.
 */
export function ShorthandNumberField({
  value,
  defaultValue = null,
  onValueChange,
  locale = "en-US",
  min,
  max,
  unit = "",
  display = "full",
  name,
  labels: labelOverrides,
  form,
  disabled,
  placeholder = "e.g. 250k",
  className,
  onBlur,
  onKeyDown,
  ref,
  "aria-describedby": describedBy,
  ...props
}: ShorthandNumberFieldProps) {
  const base = useId();
  const noteId = `${base}-note`;
  const labels: ShorthandLabels = { ...DEFAULT_LABELS, ...labelOverrides };
  const [own, setOwn] = useState<number | null>(defaultValue);
  const current = value === undefined ? own : value;
  const [draft, setDraft] = useState(() => (current === null ? "" : write(current, display, locale)));
  const [synced, setSynced] = useState(value);
  const [error, setError] = useState<string | null>(null);
  const [said, setSaid] = useState("");
  const input = useRef<HTMLInputElement | null>(null);
  const reported = useRef<number | null | undefined>(undefined);
  const timer = useRef<number | undefined>(undefined);
  // The field keeps the ref you pass and uses its own to move the focus.
  const attach = useCallback(
    (node: HTMLInputElement | null) => {
      input.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  // A number that arrives from outside replaces what is typed; an echo of what was just reported changes nothing.
  if (value !== undefined && value !== synced) {
    setSynced(value);
    if (value !== reported.current) {
      setDraft(value === null ? "" : write(value, display, locale));
      setError(null);
    }
  }

  useEffect(trackPress, []);
  useEffect(() => () => window.clearTimeout(timer.current), []);

  // What a screen reader was told stays only while it is news; left in the live region it would be read again together with the next message.
  useEffect(() => {
    if (!said) return;
    const clear = window.setTimeout(() => setSaid(""), 5000);
    return () => window.clearTimeout(clear);
  }, [said]);

  const withUnit = (figure: string) => (unit ? `${figure} ${unit}` : figure);

  /** What is wrong with this number, in words, or null. */
  function problemOf(number: number): string | null {
    if (min !== undefined && number < min) return labels.atLeast(withUnit(formatFull(min, locale)));
    if (max !== undefined && number > max) return labels.atMost(withUnit(formatFull(max, locale)));
    return null;
  }

  function report(number: number | null, valid: boolean) {
    reported.current = number;
    if (value === undefined) setOwn(number);
    onValueChange?.(number, { valid });
  }

  const reading = readShorthand(draft, locale, unit);
  const figure = reading.kind === "number" ? formatFull(reading.value, locale) : null;
  // The figure under the field is for shorthand; a text that already is the figure needs no echo.
  const echo = figure !== null && figure !== draft.trim();

  function change(event: ChangeEvent<HTMLInputElement>) {
    const text = event.target.value;
    setDraft(text);
    window.clearTimeout(timer.current);
    setSaid("");
    // A message that is already showing follows the typing and goes as soon as the text is right. A new one waits for the field to be left.
    setError((now) => {
      if (now === null) return null;
      const next = readShorthand(text, locale, unit);
      return next.kind === "unreadable" ? labels.unreadable(EXAMPLES) : next.kind === "number" ? problemOf(next.value) : null;
    });
    const next = readShorthand(text, locale, unit);
    if (next.kind === "number") {
      const spoken = labels.said(formatFull(next.value, locale), unit);
      timer.current = window.setTimeout(() => setSaid(spoken), 700);
    }
  }

  /** The number is settled: written the way `display` says, reported once, and any problem said in words. */
  function commit() {
    window.clearTimeout(timer.current);
    const settled = readShorthand(draft, locale, unit);
    if (settled.kind === "empty") {
      setDraft("");
      if (current !== null) report(null, false);
      whenReleased(() => setError(null));
      return;
    }
    if (settled.kind === "unreadable") {
      if (current !== null) report(null, false);
      whenReleased(() => setError(labels.unreadable(EXAMPLES)));
      return;
    }
    const problem = problemOf(settled.value);
    setDraft(write(settled.value, display, locale));
    if (settled.value !== current || problem !== null) report(settled.value, problem === null);
    whenReleased(() => {
      setError(problem);
      if (problem) setSaid(problem);
    });
  }

  function leave(event: FocusEvent<HTMLInputElement>) {
    onBlur?.(event);
    commit();
  }

  function keyDown(event: KeyboardEvent<HTMLInputElement>) {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.nativeEvent.isComposing) return;
    if (event.key === "Enter") commit();
    else if (event.key === "Escape") {
      // Back to the last number, as when the field was entered.
      event.preventDefault();
      setDraft(current === null ? "" : write(current, display, locale));
      setError(null);
    }
  }

  // The empty space in the field is part of the field: a click there puts the cursor in the number.
  function focusNumber(event: MouseEvent<HTMLDivElement>) {
    if (event.target !== input.current) input.current?.focus();
  }

  const invalid = error !== null;

  return (
    <div data-slot="shorthand-number-field" className={cn("grid w-full min-w-0 grid-cols-1", className)}>
      <InputGroup onClick={focusNumber} className={cn("cursor-text", invalid && WRONG)}>
        <InputGroupInput
          ref={attach}
          type="text"
          inputMode="text"
          enterKeyHint="done"
          autoComplete="off"
          autoCapitalize="off"
          autoCorrect="off"
          spellCheck={false}
          form={form}
          disabled={disabled}
          placeholder={placeholder}
          {...props}
          aria-label={props.id === undefined && props["aria-label"] === undefined && props["aria-labelledby"] === undefined ? labels.name : props["aria-label"]}
          aria-invalid={invalid || undefined}
          aria-describedby={[describedBy, noteId].filter(Boolean).join(" ")}
          value={draft}
          onChange={change}
          onBlur={leave}
          onKeyDown={keyDown}
          className="tabular-nums"
        />
        {unit ? (
          <span aria-hidden="true" className="flex h-full shrink-0 items-center rounded-r-[inherit] border-l border-border bg-muted/50 px-3 text-[0.8125rem] font-medium text-muted-foreground">
            {unit}
          </span>
        ) : null}
      </InputGroup>
      <div id={noteId} className="mt-1.5 min-h-5 text-xs">
        <div aria-live="polite">
          {error ? (
            <p className="flex items-start gap-1.5 text-destructive">
              <IconAlertCircle aria-hidden="true" className="mt-px size-3.5 shrink-0" />
              {error}
            </p>
          ) : null}
        </div>
        {error ? null : echo ? (
          <p className={cn("text-muted-foreground tabular-nums", disabled && "opacity-50")}>
            <span aria-hidden="true">= </span>
            <span className="font-medium text-foreground">{figure}</span>
            {unit ? ` ${unit}` : ""}
          </p>
        ) : (
          <p className={cn("text-muted-foreground", disabled && "opacity-50")}>{labels.hint}</p>
        )}
      </div>
      <span role="status" className="sr-only">
        {said}
      </span>
      {name ? <input type="hidden" name={name} form={form} value={current === null ? "" : String(current)} disabled={disabled} /> : null}
    </div>
  );
}

/** The words the field says, in the line under it and to a screen reader. Each can be replaced, for another language or your own voice. */
export interface ShorthandLabels {
  /** The name of the field for a screen reader when it has no label, id or aria-label of its own. */
  name: string;
  /** What the line under the field says while nothing is typed: the forms that are understood. */
  hint: string;
  /** What a screen reader hears once the typing pauses: the full figure, with the unit. */
  said: (figure: string, unit: string) => string;
  /** Said when the text is not a number. `examples` are forms that would work. */
  unreadable: (examples: string) => string;
  /** The number is below the lowest allowed. `limit` is that number, written out with its unit. */
  atLeast: (limit: string) => string;
  /** The number is above the highest allowed. */
  atMost: (limit: string) => string;
}

export const DEFAULT_LABELS: ShorthandLabels = {
  name: "Number",
  hint: "Try 250k, 1.2M or 3b.",
  said: (figure, unit) => (unit ? `${figure} ${unit}` : figure),
  unreadable: (examples) => `That is not a number I can read. Try ${examples}.`,
  atLeast: (limit) => `Enter at least ${limit}.`,
  atMost: (limit) => `Enter at most ${limit}.`,
};

/** How a number is written when the field is left: the whole figure, or short with a letter. */
export type ShorthandDisplay = "full" | "compact";

const SUFFIXES: Readonly<Record<string, number>> = {
  k: 1e3,
  thousand: 1e3,
  m: 1e6,
  million: 1e6,
  b: 1e9,
  bn: 1e9,
  billion: 1e9,
  t: 1e12,
  tn: 1e12,
  trillion: 1e12,
};

const LETTERS: readonly (readonly [number, string])[] = [
  [1e12, "T"],
  [1e9, "B"],
  [1e6, "M"],
  [1e3, "K"],
];

const formats = new Map<string, Intl.NumberFormat>();

/** A number format, kept: building one is far slower than using it, and a field asks on every keystroke. */
function numberFormat(locale: string, options: Intl.NumberFormatOptions): Intl.NumberFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let format = formats.get(key);
  if (!format) {
    try {
      format = new Intl.NumberFormat(locale, options);
    } catch {
      format = new Intl.NumberFormat("en-US", options);
    }
    formats.set(key, format);
  }
  return format;
}

/** The decimal and the grouping sign of a locale. 12345.6 is used because some locales (Spanish, Polish) only group from five digits. */
function separatorsOf(locale: string): { decimal: string; group: string } {
  const parts = numberFormat(locale, { useGrouping: true, minimumFractionDigits: 1 }).formatToParts(12345.6);
  return { decimal: parts.find((part) => part.type === "decimal")?.value ?? ".", group: parts.find((part) => part.type === "group")?.value ?? "," };
}

/**
 * The digits and separators of a keyboard in another script (Arabic-Indic,
 * Persian) and the typographic minus and apostrophe, as plain characters.
 * Written by code point, so the source stays ASCII.
 */
function asciiNumber(text: string): string {
  let plain = "";
  for (const char of text) {
    const code = char.charCodeAt(0);
    if (code >= 0x660 && code <= 0x669) plain += String(code - 0x660);
    else if (code >= 0x6f0 && code <= 0x6f9) plain += String(code - 0x6f0);
    else if (code === 0x66b) plain += ".";
    else if (code === 0x66c) plain += ",";
    else if (code === 0x2212 || (code >= 0x2010 && code <= 0x2015)) plain += "-";
    else if (code === 0x2019) plain += "'";
    else if (code === 0xa0 || code === 0x202f) plain += " ";
    else plain += char;
  }
  return plain;
}

/** Which sign in the text is the decimal one, or null when there is none ("1.234.567" has only grouping). */
function decimalSign(body: string, locale: string): string | null {
  const marks = body.match(/[.,]/g);
  if (!marks) return null;
  // Both are there ("1.234,56", "1,234.56"): the last one is the decimal sign.
  if (new Set(marks).size === 2) return body.lastIndexOf(".") > body.lastIndexOf(",") ? "." : ",";
  // The same sign twice or more is only grouping.
  if (marks.length > 1) return null;
  const mark = marks[0] ?? ".";
  const [before = "", after = ""] = body.split(mark);
  // The locale's own sign is a decimal. The other one is accepted as a decimal too ("1,2k" in English), unless it looks like a thousand ("1,200").
  if (mark === separatorsOf(locale).decimal) return mark;
  return after.length === 3 && /^[1-9]\d{0,2}$/.test(before) ? null : mark;
}

/** What the text came to: nothing at all, a number, or something that is not one. */
export type Reading = { kind: "empty" } | { kind: "number"; value: number } | { kind: "unreadable" };

/**
 * The text as a number. k, m, b and t after the digits (or thousand, million,
 * billion and trillion in words) stand for a thousand, a million, a billion and
 * a trillion, so "250k" is 250000 and "1.2 million" is 1200000. The decimal
 * sign is the locale's, and the other one is understood too, so "1,2k" and
 * "1.2k" both mean 1200 while "1,200" is twelve hundred. A currency sign in
 * front and the field's own unit behind are ignored, and so are spaces, which
 * French and Swiss people use to group digits. The sums are done on the digits
 * themselves, so 1.1k is exactly 1100.
 */
export function readShorthand(raw: string, locale: string, unit = ""): Reading {
  // A run of spaces is one space, and nothing that is a number is long: this keeps a pasted wall of text from making the check slow.
  let text = asciiNumber(raw).replace(/\s+/g, " ").trim().toLowerCase();
  if (!text) return { kind: "empty" };
  if (text.length > 80) return { kind: "unreadable" };
  text = text.replace(/^([+-]?)\s*[$€£¥]\s*/, "$1");
  const word = unit.trim().toLowerCase();
  if (word && text.endsWith(word)) text = text.slice(0, text.length - word.length).trim();
  if (!text) return { kind: "empty" };
  const match = /^([+-])?\s*((?:\d|[.,]\d)[\d.,'\s]*?)\s*([a-z]*)$/.exec(text);
  if (!match) return { kind: "unreadable" };
  const multiplier = match[3] ? SUFFIXES[match[3]] : 1;
  if (multiplier === undefined) return { kind: "unreadable" };
  const body = (match[2] ?? "").replace(/[\s']/g, "");
  const sign = decimalSign(body, locale);
  const at = sign === null ? -1 : body.lastIndexOf(sign);
  const whole = (at === -1 ? body : body.slice(0, at)).replace(/[.,]/g, "");
  const fraction = at === -1 ? "" : body.slice(at + 1).replace(/[.,]/g, "");
  const scaled = Number(`${whole || "0"}${fraction}`);
  if (!Number.isSafeInteger(scaled)) return { kind: "unreadable" };
  // Zeros first, then the move of the point: a multiplier is a power of ten, so the sum stays on whole numbers for as long as it can.
  const zeros = Math.round(Math.log10(multiplier));
  const value = fraction.length <= zeros ? scaled * 10 ** (zeros - fraction.length) : scaled / 10 ** (fraction.length - zeros);
  if (!Number.isFinite(value) || Math.abs(value) > Number.MAX_SAFE_INTEGER) return { kind: "unreadable" };
  return { kind: "number", value: match[1] === "-" && value !== 0 ? -value : value };
}

/** The whole figure as the locale writes it, with grouping: 1,200 or 1.200. */
export function formatFull(value: number, locale: string): string {
  return numberFormat(locale, { useGrouping: true, maximumFractionDigits: 10 }).format(value);
}

/** The figure short with a letter, 1.2K or 3B, when that loses nothing (two decimals at most); the whole figure when it would. */
export function formatCompact(value: number, locale: string): string {
  const size = Math.abs(value);
  for (const [multiplier, letter] of LETTERS) {
    if (size < multiplier) continue;
    const scaled = value / multiplier;
    if (Math.abs(scaled * 100 - Math.round(scaled * 100)) > 1e-6) break;
    return `${numberFormat(locale, { useGrouping: true, maximumFractionDigits: 2 }).format(scaled)}${letter}`;
  }
  return formatFull(value, locale);
}

/** A number as the field writes it when it is left. */
export const write = (value: number, display: ShorthandDisplay, locale: string): string => (display === "compact" ? formatCompact(value, locale) : formatFull(value, locale));

// A message that appears while a finger or a mouse button is still down moves the next control from under the pointer and swallows its click (the usual way
// a blur check eats a submit), so such a message waits until the press is over.
//
// A mouse press moves the focus while the button is down. A touch tap does not: it runs pointerdown, touchstart, pointerup, touchend, and only then the mouse
// events the browser makes up (mousedown, which moves the focus and blurs the field, then mouseup and click). So a press is armed by pointerdown, mousedown and
// touchstart alike, and a release only counts when no newer press began after it was announced.

/** A press that began longer ago than this is taken to be stuck (its release never arrived), not to be the one that blurred the field. */
const STALE_MS = 3000;

let pressed = false;
let pressedAt = 0;
let presses = 0;
let tracking = false;
const afterRelease: (() => void)[] = [];

/** Starts watching presses for the whole page, once. Call it from an effect. */
export function trackPress(): void {
  if (tracking) return;
  tracking = true;
  const press = () => {
    pressed = true;
    pressedAt = performance.now();
    presses += 1;
  };
  const release = () => {
    const seen = presses;
    window.setTimeout(() => {
      // Touch makes its mouse events after it has released: a press that began since then is still going on.
      if (seen !== presses) return;
      pressed = false;
      for (const run of afterRelease.splice(0)) run();
    }, 0);
  };
  // Passive: these only watch, and a touch listener that could cancel would hold the page's scrolling back.
  const options = { capture: true, passive: true };
  for (const type of ["pointerdown", "mousedown", "touchstart"] as const) document.addEventListener(type, press, options);
  for (const type of ["pointerup", "pointercancel", "mouseup", "touchend", "touchcancel", "click"] as const) document.addEventListener(type, release, options);
}

/** Runs `run` now, or, while a press is going on, as soon as it is over. */
export function whenReleased(run: () => void): void {
  if (pressed && performance.now() - pressedAt < STALE_MS) afterRelease.push(run);
  else run();
}
